def merge_intervals(intervals):
    if not intervals:
        return []
    intervals.sort()
    result = []
    current = intervals[0]
    for start, end in intervals[1:]:
        if start <= current[1]:
            current = (min(start, current[0]), max(end, current[1]))
        else:
            result.append(current)
            current = (start, end)
    result.append(current)
    return result
